function loc(){return (state.data&&state.data.locale&&locales[state.data.locale])?state.data.locale:'ru'}function t(){return locales[loc()]}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function haptic(){try{tg&&tg.HapticFeedback&&tg.HapticFeedback.selectionChanged()}catch{}}
