function statusColor(s){s=String(s||'').toUpperCase();if(s==='PAYMENT_PENDING')return'var(--orange)';if(s==='PAID'||s==='BOOKING_CONFIRMED')return'var(--green)';if(s==='DOCUMENTS_READY'||s==='READY_TO_TRAVEL')return'var(--teal)';if(s==='IN_TRIP')return'var(--blue)';if(s==='COMPLETED')return'var(--indigo)';if(s==='CANCELLED')return'var(--red)';return'var(--yellow)'}function statusText(s){return(statusNames[loc()]||statusNames.ru)[String(s||'').toUpperCase()]||String(s||'')}
