function timerHTML(){const l=current().lifecycle||{};state.deadline=l.deadlineAt||null;if(!state.deadline||l.kind==='none')return'';return '<div class="timer"><small>'+esc(timerCopy(l.kind))+'</small><strong id="countdown">00:00:00</strong><p>'+esc(t().workBody)+'</p></div>'}
function statusCard(){const s=tr().status||b().status||'AVAILABILITY_CHECK';return '<div class="detail-card status-card" style="--status:'+statusColor(s)+'"><div class="status-head"><div class="status-icon">'+ci(statusMap[s]>=3?'check':'clock')+'</div><div><h2>'+esc(statusText(s))+'</h2><p>'+esc(t().workBody)+'</p></div></div>'+timerHTML()+'</div>'}
