function identity(){const q=b(),r=q.route||{},input=q.input||{},n=input.travelers&&input.travelers.totalPeople||1;return '<section class="identity"><div class="identity-icon">'+ci('briefcase')+'</div><div class="eyebrow">'+esc(t().your)+'</div><div class="route">'+esc((r.originCode||'TAS')+' → '+(r.outboundDestination||input.arrivalAirportCode||'JED'))+'</div><div class="dates">'+esc(formatDate(input.startDate)+' – '+formatDate(input.endDate))+'</div><div class="pills"><div class="pill">'+esc(ref())+'</div><div class="pill">'+ci('person2')+' '+esc(String(n))+'</div></div></section>'}
