function hotelImage(role){const o=resolveHotel(role),snap=o.snap,d=o.detail;if(snap.coverImageURL)return snap.coverImageURL;if(d&&Array.isArray(d.images)){const c=d.images.find(x=>x.isCover)||d.images[0];if(c&&c.url)return c.url}return''}
