function sheet(content){const n=document.createElement('div');n.className='sheet';n.innerHTML='<div class="sheet-box"><div class="sheet-grabber"></div>'+content+'</div>';document.body.appendChild(n);return n}
function contactSheet(){const p=b().pilgrimProfile||{},n=sheet('<div class="sheet-head"><h2>'+esc(t().contacts)+'</h2><button class="sheet-close" data-close>'+ci('back')+'</button></div><input id="tgField" class="field" placeholder="Telegram" value="'+esc(p.telegram||'')+'"><input id="waField" class="field" placeholder="WhatsApp" value="'+esc(p.whatsapp||'')+'"><button id="saveContact" class="btn primary">'+esc(t().save)+' '+ci('check')+'</button>');n.querySelector('[data-close]').onclick=()=>n.remove();n.querySelector('#saveContact').onclick=async()=>{await mutate('contacts',{telegram:n.querySelector('#tgField').value,whatsapp:n.querySelector('#waField').value});n.remove()}}
async function openHotels(role){state.hotelRole=role;const n=sheet('<div class="sheet-head"><div><h2>'+esc(t().chooseHotel)+'</h2><div class="updates" style="margin-top:4px">'+esc(t().chooseHotelBody)+'</div></div><button class="sheet-close" data-close>'+ci('back')+'</button></div><div id="hotelList" class="loading"><div class="spinner"></div>'+esc(t().loading)+'</div>');n.querySelector('[data-close]').onclick=()=>n.remove();try{const x=await api('/mini/hotels',{bookingId:b().id,role:role});state.hotels=x.hotels||[];renderHotelList(n)}catch(e){n.querySelector('#hotelList').innerHTML='<div class="loading">'+esc(e.message||t().noHotels)+'</div>'}}
